<section class="page-head"><span class="eyebrow">LIBRARY</span><h1>Games</h1><p>Browse the titles tracked by GameScore.</p></section><div class="game-grid wide"><?php foreach($games as $g):?><a class="game-card" href="<?=url('/game/'.e($g['slug']))?>"><div class="game-art" style="background-image:url('<?=e($g['image_url']?:'https://images.unsplash.com/photo-1511512578047-dfb367046420?auto=format&fit=crop&w=1000&q=80')?>')"><span>Open</span></div><h3><?=e($g['name'])?></h3><?php if(setting_value('games_show_descriptions',true)):?><p><?=e($g['description'])?></p><?php endif;?></a><?php endforeach;if(!$games):?><div class="empty">No published games are available.</div><?php endif;?></div>